using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
public static class Native67DanceJointAudit {
 [Serializable] class Report {public string status,error,note="Normalized by bind hip-to-ankle height; each pose expressed in its hips/head/leg body basis. Shoulder means upper-arm joint, not clavicle root. These measurements compare proportion/motion, not anatomical acceptance.";public Native67AlternativeDanceReview.Evidence[] evidence;public Native67AlternativeDanceReview.JointPose[] poses;}
 public static void Run(){var r=new Report();GameObject actor=null;Native67AlternativeDanceReview a=null;int code=1;try{actor=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Native67SpatialReview/SailorReview.fbx"));a=new Native67AlternativeDanceReview(actor,actor.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single());foreach(int id in new[]{66,65,64,67,63,74,77,75,70,71,82}){var c=a.Prepare("action-"+id);foreach(float phase in (Environment.GetEnvironmentVariable("LF_NATIVE67_DENSE_AUDIT")=="1"?Enumerable.Range(0,101).Select(i=>i/100f).ToArray():new[]{0f,.1f,.3f,.5f,.7f,.9f})){a.Sample(c.length*phase);a.Measure(c.length*phase);}}r.evidence=a.evidence.ToArray();r.poses=a.jointPoses.ToArray();r.status="MEASURED_NOT_ANATOMICAL_ACCEPTANCE";code=0;}catch(Exception e){r.status="FAILED";r.error=e.ToString();}finally{a?.Dispose();if(actor!=null)UnityEngine.Object.DestroyImmediate(actor);File.WriteAllText(Environment.GetEnvironmentVariable("LF_NATIVE67_REPORT"),JsonUtility.ToJson(r,true));EditorApplication.Exit(code);}}
}
